/* HIA Theme Builder 生成 — HIA Next.js 主题（app/globals.css 追加段）
   Generated by HIA Theme Builder — target: Next.js App Router.
   用法：将以下内容追加到 app/globals.css（Tailwind v4 项目自带 @import 'tailwindcss'）。
   亮/暗切换：Tailwind v4 类策略（@custom-variant dark），html.dark 时变量自动换档。 */

/* ===== HIA 令牌（亮态）===== */
:root {
  --hia-primary: #0047AB;
  --hia-primary-deep: #04234F;
  --hia-primary-soft: #EFF6FF;
  --hia-secondary: #00A8D3;
  --hia-on-primary: #FFFFFF;
  --hia-text: #04234F;
}

/* ===== HIA 令牌（暗态：html.dark 时自动换档）===== */
.dark {
  --hia-primary: #93C5FD;
  --hia-primary-deep: #EFF6FF;
  --hia-primary-soft: #0B1E3C;
  --hia-secondary: #67E8F9;
  --hia-on-primary: #0B1E3C;
  --hia-text: #DBEAFE;
}

/* ===== 组件应用（可选示例）===== */
body { color: var(--hia-text); }
a { color: var(--hia-primary); }
.dark a { color: var(--hia-primary); }
